  {
  }

  lemma RetrieveStakeholderInfoEnsures(m: Model, id: string)
    ensures (match Apply(m, RetrieveStakeholderInfo(id))
      case result => 
        forall k | k in result :: k != "password" && k != "ssn"
    )
  {
